window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-inbox-sla.html"]="<!-- Settings: SLA -->\n<style>\n.sla-form{background:var(--card);border:1px solid var(--border);border-radius:8px;padding:24px;max-width:480px}\n.sla-form label{display:block;margin-bottom:16px;font-size:13px;font-weight:600}\n.sla-form input[type=number]{width:120px;margin-left:12px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:var(--bg);text-align:center}\n.sla-form .hint{font-size:11px;color:var(--muted);margin-top:4px}\n.sla-visual{margin-top:24px;display:flex;gap:16px}\n.sla-visual .card{flex:1;padding:20px;text-align:center}\n.sla-visual .big{font-size:28px;font-weight:800;color:var(--accent)}\n.sla-visual .lbl{font-size:12px;color:var(--muted);margin-top:4px}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">🏢 Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">👥 Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">🔐 Peran</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">🏷️ Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">🕐 Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">🔄 Auto-Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">📥 Tim Inbox</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/inbox-sla')\">⏱️ SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">⭐ CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">⚡ Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">🎫 Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">🟢 WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">🔵 WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">💬 Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">🔗 Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <h2 style=\"margin:0 0 4px\">⏱️ SLA (Service Level Agreement)</h2>\n    <p style=\"color:var(--muted);font-size:13px;margin:0 0 20px\">Atur target waktu respon pertama dan waktu penyelesaian percakapan.</p>\n\n    <div class=\"sla-form\">\n      <label>Respon Pertama (menit)\n        <input type=\"number\" id=\"slaFirst\" min=\"1\" value=\"60\" onchange=\"saveSla()\">\n        <div class=\"hint\">Target waktu agen membalas pesan pertama pelanggan</div>\n      </label>\n      <label>Waktu Penyelesaian (menit)\n        <input type=\"number\" id=\"slaResolve\" min=\"1\" value=\"240\" onchange=\"saveSla()\">\n        <div class=\"hint\">Target waktu menyelesaikan percakapan dari awal hingga tutup</div>\n      </label>\n    </div>\n\n    <div class=\"sla-visual\">\n      <div class=\"card\">\n        <div class=\"big\" id=\"slaFirstFmt\">1 jam</div>\n        <div class=\"lbl\">Respon Pertama</div>\n      </div>\n      <div class=\"card\">\n        <div class=\"big\" id=\"slaResolveFmt\">4 jam</div>\n        <div class=\"lbl\">Penyelesaian</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  const sla = DB.settings.sla;\n  document.getElementById('slaFirst').value = sla.firstResponse;\n  document.getElementById('slaResolve').value = sla.resolveTime;\n  updateVisual();\n})();\n\nfunction fmtMinutes(mins){\n  if(mins < 60) return mins + ' mnt';\n  const h = Math.floor(mins/60);\n  const m = mins % 60;\n  return m ? h+' jam '+m+' mnt' : h+' jam';\n}\n\nfunction updateVisual(){\n  const fr = parseInt(document.getElementById('slaFirst').value)||0;\n  const rt = parseInt(document.getElementById('slaResolve').value)||0;\n  document.getElementById('slaFirstFmt').textContent = fmtMinutes(fr);\n  document.getElementById('slaResolveFmt').textContent = fmtMinutes(rt);\n}\n\nfunction saveSla(){\n  const fr = parseInt(document.getElementById('slaFirst').value)||60;\n  const rt = parseInt(document.getElementById('slaResolve').value)||240;\n  DB.settings.sla = {firstResponse:fr, resolveTime:rt};\n  saveStore();\n  updateVisual();\n  showToast('Pengaturan SLA disimpan');\n}\n</script>\n";
